app.command("/nova", async ({ ack, command, respond }) => {
  await ack(); // Slack waits at most 3 seconds; the work comes after
  const { verb, key } = parseNova(command.text); // "/nova RH-1234" means start
  const by = people.bySlackId(command.user_id); // config/people.yaml: Slack ID -> Jira account, GitHub login, email
  const run = temporal.workflow.getHandle(`nova:${key}`);
  if (verb === "start") {
    await jira.setIssueProperty(key, "nova.requester", by.jiraAccountId);
    await jira.assign(key, NOVA_ACCOUNT_ID); // the Jira poll starts the run, like any other hand-off
    return respond(`Nova has ${key}. Follow along in its thread.`);
  }
  if (verb === "status") return respond(oneLine(await run.query(status))); // the run's own answer
  if (verb === "stop") {
    await run.signal(stop, by.email);
    return respond(`Stopping ${key}. The branch and notes are kept.`);
  }
  await respond(USAGE);
});

app.event("message", async ({ event, client }) => {
  if (event.subtype !== undefined || event.bot_id || !event.thread_ts) return; // people only, inside a thread
  const workflowId = await workflowForThread(event.channel, event.thread_ts); // the broker's record, every time
  if (!workflowId) return; // a thread that belongs to no run
  const person = people.bySlackId(event.user);
  try {
    await temporal.workflow.getHandle(workflowId).signal(answerQuestion, event.text ?? "", person.email);
  } catch { // Temporal unreachable: tell the person, never drop an answer silently
    await client.chat.postEphemeral({ channel: event.channel, user: event.user,
      text: "Your answer didn't reach Nova. Please send it again in a minute." });
  }
});

