// A pretend Slack Web API on your laptop: it prints every call the app or the broker makes.
import { createServer } from 'node:http';

let n = 0;
createServer((req, res) => {
  let body = '';
  req.on('data', (c) => (body += c));
  req.on('end', () => {
    const method = req.url.replace('/api/', '');
    const args = req.headers['content-type']?.includes('json') ? JSON.parse(body) : Object.fromEntries(new URLSearchParams(body));
    res.setHeader('content-type', 'application/json');
    if (method === 'auth.test') return res.end(JSON.stringify({ ok: true, user_id: 'U_NOVA', bot_id: 'B_NOVA' }));
    const where = method === 'respond' ? '(only you see this)' : args.thread_ts ? `in thread ${args.thread_ts}` : `ts=${args.ts ?? '(new)'}`;
    console.log(`${method.padEnd(16)} ${where.padEnd(28)} ${args.text}`);
    res.end(JSON.stringify({ ok: true, channel: args.channel, ts: args.ts ?? `${Math.floor(Date.now() / 1000)}.${String(++n).padStart(6, "0")}` }));
  });
}).listen(process.env.SLACK_PORT ?? 3999, () => console.log('fake Slack API listening'));
EOF
cat > slack.mjs <<'EOF'
// Plays Slack: signs a request the way Slack does and sends it to the app.
//   node slack.mjs reply U_SEAN "text"      a person replies in RH-1234's thread
//   node slack.mjs bot "text"               Nova's own message in the thread, as Slack echoes it
//   node slack.mjs command "/nova status RH-1234"
import { createHmac } from 'node:crypto';
import { readFileSync } from 'node:fs';

const [kind, a, b] = process.argv.slice(2);
// Slack knows which thread you typed in; here we look up RH-1234's newest thread in the broker's record.
const thread = () => Object.entries(JSON.parse(readFileSync('threads.json', 'utf8'))).findLast(([, id]) => id === 'nova:RH-1234')?.[0];
const event = (fields) => JSON.stringify({ type: 'event_callback', event_id: `Ev${Date.now()}`,
  event: { type: 'message', channel: 'C_NOVA', ts: `${Date.now() / 1000}`, thread_ts: thread(), ...fields } });
const body = kind === 'command'
  ? new URLSearchParams({ command: a.split(' ')[0], text: a.split(' ').slice(1).join(' '), user_id: 'U_SEAN', channel_id: 'C_NOVA',
      response_url: `http://localhost:${process.env.SLACK_PORT ?? 3999}/api/respond` }).toString()
  : kind === 'bot' ? event({ bot_id: 'B_NOVA', text: a }) : event({ user: a, text: b });
const ts = Math.floor(Date.now() / 1000);
const sig = 'v0=' + createHmac('sha256', 'lab-secret').update(`v0:${ts}:${body}`).digest('hex');
const type = kind === 'command' ? 'application/x-www-form-urlencoded' : 'application/json';
const res = await fetch(`http://localhost:${process.env.PORT ?? 3000}/slack/events`, { method: 'POST', body,
  headers: { 'content-type': type, 'x-slack-request-timestamp': ts, 'x-slack-signature': sig } });
console.log(`app answered ${res.status}`);
EOF
