// Stand-ins for the broker's Slack calls and for the VM. The broker posts in the pretend Slack and records
// in threads.json which run owns which thread, so nothing depends on the Slack app's memory.
import { readFile, writeFile } from 'node:fs/promises';
import { sleep } from '@temporalio/activity';

const slack = async (method, args) => {
  const res = await fetch(`http://localhost:${process.env.SLACK_PORT ?? 3999}/api/${method}`,
    { method: 'POST', body: new URLSearchParams({ channel: 'C_NOVA', ...args }) });
  return res.json();
};
const now = () => new Date().toTimeString().slice(0, 8);

// The ticket's thread starts with its status message. The broker records thread -> run.
export const openThread = async (workflowId, key) => {
  const { ts } = await slack('chat.postMessage', { text: `${key} · Nova: Checking` });
  const threads = JSON.parse(await readFile('threads.json', 'utf8').catch(() => '{}'));
  await writeFile('threads.json', JSON.stringify({ ...threads, [ts]: workflowId }) + '\n');
  return ts;
};

// One status message, edited in place: same ts every time.
export const setStatus = async (ts, key, state) => { await slack('chat.update', { ts, text: `${key} · Nova: ${state}` }); };

export const ask = async (ts, question) => { await slack('chat.postMessage', { thread_ts: ts, text: question }); };

export const wakeSandbox = async (key) => {
  console.log(`${now()}  ${key}  waking the parked VM (10 seconds)`);
  await sleep(10_000);
};

export const resume = async (key, answer) => console.log(`${now()}  ${key}  Nova resumes the session with:\n${answer}`);
EOF
cat > workflows.mjs <<'EOF'
// Nova's run for one ticket, cut down to one question in its Slack thread.
import { condition, defineQuery, defineSignal, proxyActivities, setHandler, workflowInfo } from '@temporalio/workflow';

const act = proxyActivities({ startToCloseTimeout: '1 minute' });

export const answerQuestion = defineSignal('answerQuestion');
export const statusQuery = defineQuery('status');

export async function ticketToPr(t) {
  let state = 'Checking';
  const replies = [];
  setHandler(statusQuery, () => state);
  setHandler(answerQuestion, (text, by) => { replies.push(`${by}: ${text}`); }); // every reply is kept

  const thread = await act.openThread(workflowInfo().workflowId, t.key);
  const set = async (s) => { state = s; await act.setStatus(thread, t.key, s); };
  await set('Working');
  await act.ask(thread, 'Should the empty card have a Create project button?');
  await set('Needs info');
  if (!(await condition(() => replies.length > 0, '10 minutes'))) return 'nobody answered';
  await act.wakeSandbox(t.key); // replies that arrive while the VM wakes up are joined into one answer
  await set('Working');
  await act.resume(t.key, replies.join('\n'));
  await set('PR open');
  return replies.join(' | ');
}
EOF
